import * as React from "react";

export type LakeIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function LakeIcon({ size = 20, ...props }: LakeIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="11" r="6.5"/><path d="M7 10.5h4M10 13.5h5"/>
    </svg>
  );
}
